// menu.c - generated by split_c.py from main_menu.c
#include "menu_priv.h"



//*****************************************************************************
// App callbacks
//*****************************************************************************

// Called once each time the menu appears: full draw, selection centered.
static void Menu_Init(void)
{
    int16_t count = (int16_t)g_appCount;

    menu_bg = Menu_BgColor(Menu_GetBg());      // saved background color
    menu_Menu_DrawStatic();

    menu_drawFrame  = false;
    menu_drawSides  = false;
    menu_needSettle = false;
    menu_glyphsOn   = false;
    menu_lblSel     = -1;
    menu_pgSel      = -1;

    if(count < 1)
        return;                             // nothing to show

    if(menu_sel >= count)
        menu_sel = 0;

    menu_pos      = (int32_t)menu_sel * MENU_PITCH;
    menu_drawnPos = menu_pos;
    menu_from     = menu_pos;
    menu_target   = menu_pos;
    menu_animF    = 0;
    menu_hTimer   = 0;
    menu_pStep    = 7;
    menu_tick     = 0;
    menu_lit      = menu_sel;

    menu_Menu_UpdatePager(menu_sel, count);
    menu_Menu_UpdateLabels(menu_sel);
    menu_Menu_PaintAllTiles(menu_pos, count);
    menu_Menu_DrawGlyphs(menu_pos, count);
    menu_glyphsOn = true;
    menu_Menu_DrawFrame(menu_Menu_PulseColor(menu_sel, menu_pStep));
}


// Logic only: read input, move the selection, advance the animation, and
// record WHAT needs redrawing. No drawing here.
static AppStatus Menu_Update(void)
{
    int16_t count = (int16_t)g_appCount;
    int16_t move;
    int16_t heldDir;
    int16_t newStep;
    int16_t ns;
    int32_t u;
    int32_t e;

    if(count < 1)
        return APP_CONTINUE;

    // ---- Select: hand the chosen app to main.c and leave the menu ----------
    if(g_joy.btnPressed || MENU_SELECT_TAP)
    {
        Sfx_PlayWait(&sfx_menu_select);
        App_Launch(g_apps[menu_sel]);
        return APP_QUIT;
    }

    // ---- Requested movement -------------------------------------------------
    move = g_joy.edgeX;

    if(MENU_LEFT_TAP)
        move = -1;

    if(MENU_RIGHT_TAP)
        move = 1;

    heldDir = g_joy.dirX;

    if(MENU_LEFT_HELD && !MENU_RIGHT_HELD)
        heldDir = -1;

    if(MENU_RIGHT_HELD && !MENU_LEFT_HELD)
        heldDir = 1;

    // ---- Auto-repeat --------------------------------------------------------
    if(move != 0)
    {
        menu_hTimer = MENU_DAS_FRAMES;
    }
    else if(heldDir == 0)
    {
        menu_hTimer = 0;
    }
    else if(--menu_hTimer <= 0)
    {
        move = heldDir;
        menu_hTimer = MENU_ARR_FRAMES;
    }

    // ---- Change selected item ----------------------------------------------
    // Labels and the highlight are NOT redrawn here; they hand over when the
    // animation settles. A new target restarts the ease from where we are.
    if(move != 0)
    {
        ns = menu_sel + move;

#if MENU_WRAP
        if(ns < 0)       ns = count - 1;
        if(ns >= count)  ns = 0;
#else
        if(ns < 0)       ns = 0;
        if(ns >= count)  ns = count - 1;
#endif

        if(ns != menu_sel)
        {
            menu_sel        = ns;
            menu_from       = menu_pos;
            menu_target     = (int32_t)menu_sel * MENU_PITCH;
            menu_animF      = 0;
            menu_needSettle = true;
            menu_drawFrame  = true;            // frame color follows the app
            Buzzer_PlaySfx(&sfx_menu_move);
        }
        else if(menu_hTimer == MENU_DAS_FRAMES)        // bump only on a fresh
            Buzzer_PlaySfx(&sfx_menu_bump);         // press, not auto-repeat
    }

    // ---- Animate: fixed frame count, ease-out (fast start, soft landing) ----
    if(menu_pos != menu_target)
    {
        if(++menu_animF >= MENU_ANIM_FRAMES)
        {
            menu_pos = menu_target;
        }
        else
        {
            u = 256 - ((int32_t)menu_animF * 256) / MENU_ANIM_FRAMES;  // 256..0
            e = 256 - ((u * u) >> 8);                               // 0..256
            menu_pos = menu_from + ((menu_target - menu_from) * e) / 256;
        }

        menu_drawSides = true;                 // the strip may overwrite the side bars
    }

    // ---- Pulse --------------------------------------------------------------
#if MENU_PULSE
    menu_tick++;
    newStep = (int16_t)((menu_tick >> 2) & 15);

    if(newStep != menu_pStep)
    {
        menu_pStep = newStep;
        menu_drawFrame = true;
    }
#endif

    return APP_CONTINUE;
}


// Drawing only: do whatever Update flagged.
static void Menu_Render(void)
{
    int16_t count = (int16_t)g_appCount;
    int16_t old;

    if(count < 1)
        return;

    // ---- Scroll: repaint only the columns that changed ----------------------
    if(menu_pos != menu_drawnPos)
    {
        if(menu_glyphsOn)
        {
            menu_Menu_EraseGlyphs(menu_drawnPos, count);
            menu_glyphsOn = false;
        }

        menu_Menu_ScrollStrip(menu_drawnPos, menu_pos, count);
        menu_drawnPos = menu_pos;
    }

    // ---- Arrived: hand over the highlight, letters, pager and labels --------
    if(menu_needSettle && menu_pos == menu_target)
    {
        menu_needSettle = false;

        if(menu_lit != menu_sel)
        {
            old   = menu_lit;
            menu_lit = menu_sel;
#if MENU_DIM_BRIGHT != MENU_LIT_BRIGHT
            menu_Menu_PaintBody(old, menu_pos);         // old tile -> dim
            menu_Menu_PaintBody(menu_lit, menu_pos);       // new tile -> bright
#else
            (void)old;
#endif
        }

        menu_Menu_DrawGlyphs(menu_pos, count);
        menu_glyphsOn = true;

        menu_Menu_UpdatePager(menu_sel, count);
        menu_Menu_UpdateLabels(menu_sel);
    }

    if(menu_drawFrame)
        menu_Menu_DrawFrame(menu_Menu_PulseColor(menu_sel, menu_pStep));
    else if(menu_drawSides)
        menu_Menu_DrawFrameSides(menu_Menu_PulseColor(menu_sel, menu_pStep));

    menu_drawFrame = false;
    menu_drawSides = false;
}


// Other apps assume a BLACK drawing background (they usually just clear the
// screen), so put it back when the menu is left.
static void Menu_Exit(void)
{
    Graphics_setBackgroundColor(&g_sContext, COLOR_BLACK);
}


//*****************************************************************************
// The menu's descriptor. main.c runs it first and after every app.
// (Not listed in g_apps[], so it never appears as a tile.)
//*****************************************************************************
const App g_menuApp =
{
    "MENU", "", COLOR_WHITE, MENU_FRAME_US,
    Menu_Init, Menu_Update, Menu_Render, Menu_Exit,
    NULL,                       // not a legacy app
    NULL,                       // no redraw(): init() repaints the launcher
    &g_menuSettings             // pause menu > Menu Settings
};
